package httpapi

import (
	"encoding/json"
	"fmt"
	"log/slog"
	"net/http"
	"net/url"
	"strings"
	"sync"

	"github.com/danielgtaylor/huma/v2"
	"gopkg.in/yaml.v3"

	"github.com/medinetcore/aud/docs"
	"github.com/medinetcore/aud/internal/audit/domain"
)

// contractSchemas are the schema names the ingest contract owns: when huma generates a schema
// with the same name (the Go problem type), the contract version is published.
var contractSchemas = map[string]bool{"Problem": true}

// specHandlers serves the complete OpenAPI document (query operations generated by huma,
// ingest operations from the published contract, and /health) as JSON and YAML. The document
// is built on the first request, after every operation is registered.
func specHandlers(api huma.API) (jsonHandler, yamlHandler http.HandlerFunc) {
	build := sync.OnceValues(func() ([2][]byte, error) {
		doc, err := buildSpec(api)
		if err != nil {
			return [2][]byte{}, err
		}
		j, err := json.Marshal(doc)
		if err != nil {
			return [2][]byte{}, err
		}
		y, err := yaml.Marshal(doc)
		return [2][]byte{j, y}, err
	})
	serve := func(i int, contentType string) http.HandlerFunc {
		return func(w http.ResponseWriter, _ *http.Request) {
			docs, err := build()
			if err != nil {
				slog.Error("build OpenAPI document", "error", err)
				writeProblem(w, http.StatusInternalServerError, "internal error")
				return
			}
			w.Header().Set("Content-Type", contentType)
			w.Header().Set("X-Content-Type-Options", "nosniff")
			_, _ = w.Write(docs[i])
		}
	}
	return serve(0, "application/openapi+json"), serve(1, "application/openapi+yaml")
}

func buildSpec(api huma.API) (map[string]any, error) {
	documentQueryErrors(api.OpenAPI())

	raw, err := json.Marshal(api.OpenAPI())
	if err != nil {
		return nil, err
	}
	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return nil, err
	}
	var ingest map[string]any
	if err := yaml.Unmarshal(docs.IngestOpenAPI, &ingest); err != nil {
		return nil, fmt.Errorf("ingest contract: %w", err)
	}
	if err := mergeIngest(doc, ingest); err != nil {
		return nil, err
	}
	paths(doc)["/health"] = map[string]any{"get": healthOperation}
	doc["servers"] = []any{map[string]any{"url": "/", "description": "This AUD instance"}}
	return doc, pruneSchemas(doc)
}

// pruneSchemas removes component schemas nothing references, such as the one huma generated
// for the Go problem type before the contract's Problem replaced it.
func pruneSchemas(doc map[string]any) error {
	schemas := asMap(asMap(doc["components"])["schemas"])
	for removed := true; removed; {
		removed = false
		raw, err := json.Marshal(doc)
		if err != nil {
			return err
		}
		for name := range schemas {
			if !strings.Contains(string(raw), `"#/components/schemas/`+name+`"`) {
				delete(schemas, name)
				removed = true
			}
		}
	}
	return nil
}

// documentQueryErrors finishes the huma operations: it drops 422 (validation errors are
// answered with 400), adds an example to every error and the challenge header to 401.
func documentQueryErrors(oapi *huma.OpenAPI) {
	for _, item := range oapi.Paths {
		op := item.Get
		if op == nil {
			continue
		}
		delete(op.Responses, "422")
		roles, _ := op.Metadata[metaRoles].([]string)
		for code, resp := range op.Responses {
			if mt := resp.Content["application/problem+json"]; mt != nil {
				mt.Example = exampleProblem(code, op, roles)
			}
		}
		if resp := op.Responses["401"]; resp != nil {
			resp.Description = "Missing, malformed, expired or badly signed bearer token. The cause is not disclosed."
			resp.Headers = map[string]*huma.Param{"WWW-Authenticate": {
				Description: `Bearer challenge, e.g. Bearer realm="aud", error="invalid_token".`,
				Schema:      &huma.Schema{Type: huma.TypeString},
			}}
		}
		if resp := op.Responses["403"]; resp != nil {
			resp.Description = "Valid token without the required role (" + strings.Join(roles, " or ") + ")."
		}
	}
}

func exampleProblem(code string, op *huma.Operation, roles []string) problem {
	p := problem{Type: "about:blank"}
	_, _ = fmt.Sscan(code, &p.Status)
	p.Title = http.StatusText(p.Status)
	switch p.Status {
	case http.StatusBadRequest:
		p.Detail = "validation failed"
		field := "id"
		if len(op.Parameters) > 0 {
			field = op.Parameters[0].Name
		}
		p.Errors = []domain.FieldError{{Field: field, Message: "invalid value"}}
	case http.StatusUnauthorized:
		p.Detail = bearerDetail
	case http.StatusForbidden:
		p.Detail = "this operation requires one of the roles: " + strings.Join(roles, ", ")
	case http.StatusNotFound:
		p.Detail = "event not found"
	default:
		p.Detail = "internal error"
	}
	return p
}

// mergeIngest adds the operations and components of the ingest contract to doc. The contract's
// paths are relative to its server URL (/api/v1) and inherit its top-level security.
func mergeIngest(doc, ingest map[string]any) error {
	prefix := ""
	if servers, _ := ingest["servers"].([]any); len(servers) > 0 {
		server, _ := servers[0].(map[string]any)
		u, err := url.Parse(fmt.Sprint(server["url"]))
		if err != nil {
			return fmt.Errorf("ingest contract server: %w", err)
		}
		prefix = strings.TrimSuffix(u.Path, "/")
	}

	all := paths(doc)
	for path, item := range asMap(ingest["paths"]) {
		target := asMap(all[prefix+path])
		if target == nil {
			target = map[string]any{}
			all[prefix+path] = target
		}
		for method, op := range asMap(item) {
			if _, taken := target[method]; taken {
				return fmt.Errorf("ingest contract: %s %s is already defined", method, prefix+path)
			}
			o := asMap(op)
			if _, ok := o["security"]; !ok {
				o["security"] = ingest["security"]
			}
			o["tags"] = []any{"Ingest"}
			target[method] = o
		}
	}

	components := asMap(doc["components"])
	for section, entries := range asMap(asMap(ingest["components"])) {
		dst := asMap(components[section])
		if dst == nil {
			dst = map[string]any{}
			components[section] = dst
		}
		for name, v := range asMap(entries) {
			if _, taken := dst[name]; taken && (section != "schemas" || !contractSchemas[name]) {
				return fmt.Errorf("ingest contract: components.%s.%s is already defined", section, name)
			}
			dst[name] = v
		}
	}

	info := asMap(doc["info"])
	info["description"] = apiDescription + "\n\n## Ingest\n\n" + fmt.Sprint(asMap(ingest["info"])["description"])
	doc["tags"] = []any{
		map[string]any{"name": "Ingest", "description": "Signed with HMAC-SHA256 by the emitting modules (ingest contract)."},
		map[string]any{"name": queryTag, "description": "Bearer JWT with the auditor or admin role."},
		map[string]any{"name": "Health", "description": "Liveness probe."},
	}
	return nil
}

func paths(doc map[string]any) map[string]any {
	p := asMap(doc["paths"])
	if p == nil {
		p = map[string]any{}
		doc["paths"] = p
	}
	return p
}

func asMap(v any) map[string]any {
	m, _ := v.(map[string]any)
	return m
}

const apiDescription = `AUD (module 11 of MediNet-Core) keeps an append-only, hash-chained log of the security
events of every module.

- **Ingest** (` + "`POST /api/v1/events`, `POST /api/v1/events/batch`" + `): modules send events signed with
  HMAC-SHA256 (security schemes audClientId, audTimestamp and audSignature).
- **Query** (` + "`GET /api/v1/...`" + `): auditors and administrators read the log with a bearer JWT
  (security scheme bearer).

Every error is an RFC 7807 problem (` + "`application/problem+json`" + `); invalid parameters are answered
with 400 and listed in ` + "`errors[].field`" + `.`

var healthOperation = map[string]any{
	"operationId": "health",
	"summary":     "Liveness probe",
	"description": "Answers 200 while the process can serve requests. It needs no credentials and does not check the database.",
	"tags":        []any{"Health"},
	"security":    []any{},
	"responses": map[string]any{
		"200": map[string]any{
			"description": "The service is up.",
			"content": map[string]any{"application/json": map[string]any{
				"schema": map[string]any{
					"type":       "object",
					"required":   []any{"status"},
					"properties": map[string]any{"status": map[string]any{"type": "string", "enum": []any{"ok"}}},
				},
				"example": map[string]any{"status": "ok"},
			}},
		},
	},
}
